const input = $input.first().json;

const requestedPlatform = input.requestedPlatform;
const source = input.source;
const datasets = input.datasets;
const supportedPlatforms = Object.keys(datasets);

if (!supportedPlatforms.includes(requestedPlatform)) {
  return [
    {
      json: {
        httpStatus: 400,
        body: {
          success: false,
          source,
          error: "Unsupported platform",
          requestedPlatform,
          supportedPlatforms
        }
      }
    }
  ];
}

const analytics = datasets[requestedPlatform];

const engagementRate = analytics.reach > 0
  ? Number(((analytics.engagement / analytics.reach) * 100).toFixed(2))
  : 0;

const followerGrowthRate = analytics.followers > 0
  ? Number(((analytics.followerGrowth / analytics.followers) * 100).toFixed(2))
  : 0;

const clickThroughRate = analytics.impressions > 0
  ? Number(((analytics.linkClicks / analytics.impressions) * 100).toFixed(2))
  : 0;

return [
  {
    json: {
      httpStatus: 200,
      body: {
        success: true,
        source,
        platform: analytics.platform,
        reportingPeriod: analytics.reportingPeriod,
        views: analytics.views,
        reach: analytics.reach,
        impressions: analytics.impressions,
        engagement: analytics.engagement,
        engagementRate,
        followers: analytics.followers,
        followerGrowth: analytics.followerGrowth,
        followerGrowthRate,
        profileVisits: analytics.profileVisits,
        linkClicks: analytics.linkClicks,
        clickThroughRate,
        postsPublished: analytics.postsPublished,
        generatedAt: new Date().toISOString()
      }
    }
  }
];
